    if (d.subject != null) { q(".em-sub").value = d.subject; q(".em-title").value = d.subject || "New message"; }
    if (d.body != null) { ta.value = String(d.body).replace(/\\n/g, "\n"); fit(); ta.scrollTop = ta.scrollHeight; }
};
$("chat").appendChild(card); autoscroll();
return card;

