const engines = [
    "https://www.bing.com/search?q=" + encodeURIComponent(query) + "&count=10",
    "https://search.brave.com/search?q=" + encodeURIComponent(query) + "&source=web"
];
for (const url of engines) {
    try {
        const ctrl = new AbortController();
        const timer = setTimeout(() => ctrl.abort(), 15000);
        const r = await fetch("https://api.allorigins.win/raw?url=" + encodeURIComponent(url), { signal: ctrl.signal });
        clearTimeout(timer);
        const txt = await r.text();
        let items = [];
        if (url.includes("bing.com")) {
            const cap = [...txt.matchAll(/<li class="b_algo"[\s\S]*?<h2[^>]*><a[^>]*href="([^"]+)"[^>]*>([\s\S]*?)<\/a>[\s\S]*?<p[^>]*>([\s\S]*?)<\/p>/gi)];
            items = cap.map(m => ({ title: stripHtml(m[2]), snippet: stripHtml(m[3]), url: m[1] }));
        } else {
            const cap = [...txt.matchAll(/<a[^>]*class="[^"]*snippet[^"]*"[^>]*>([\s\S]*?)<\/a>/gi)];
            items = cap.map(m => ({ title: stripHtml(m[1]), snippet: "", url: "" }));
        }
        items = items.filter(it => it.title && it.title.length > 3).slice(0, 5);
        if (items.length) {
            return "?? **Search Results for \"" + query + "\":**\n\n" + items.map((it, n) => {
                let s2 = (n + 1) + ". " + it.title;
                if (it.snippet) s2 += " � " + it.snippet;
                if (it.url) s2 += " (" + it.url + ")";
                return s2;
            }).join("\n\n");
        }
    } catch (e) { continue; }
}
return "? Could not load search results for \"" + query + "\". Try \"read this page: <url>\" instead.";

const t = (text || "").toLowerCase();
if (/\b(python|pyodide|pandas|numpy|calculate|compute|plot|prime|fibonacci|factorial|simulate|run (this|the) code)\b/.test(t))
    return 'CONTEXT FOR THIS REQUEST: the user wants something computed or coded. Use the run_python tool: write complete, working Python that print()s its results.';
if (/\b(e-?mail|gmail|outlook|mail to|reply to)\b/.test(t))
    return 'CONTEXT FOR THIS REQUEST: your output is an EMAIL that will appear in an email editor. Use the send_email tool. The body must be the complete, ready-to-send email (greeting, full paragraphs, sign-off) with real specific details.';
if (/\b(pptx|powerpoint|presentation|slides?|slide deck)\b/.test(t))
    return 'CONTEXT FOR THIS REQUEST: your output is a POWERPOINT file. Use generate_file with type "pptx". Content = slides separated by a line containing only ---, the first line of each slide is its title, the rest is its bullet text. Write every slide fully.';
if (/\b(docx?|word|document|report|essay|letter|proposal|article|resume|cv|contract|memo|write[- ]?up|notes)\b/.test(t))
    return 'CONTEXT FOR THIS REQUEST: your output is a WORD DOCUMENT that will appear in a document editor. Use generate_file with type "docx". Content = the complete document text, full length, with a title and real sections. Do not shorten or summarise it.';
return '';

        const hint = contextHint(text);
        return `You are Yacob, a precise and capable AI assistant living inside a chat app that has built-in tools. Your output does not only become chat text: depending on the request it lands in a specific place, and you must work out which place BEFORE you write.

WHERE YOUR OUTPUT GOES
- Normal question -> plain text in a chat bubble.
- send_email -> an email editor card (To, Subject, Body). The user sends it through Gmail, Outlook or their mail app.
- generate_file, type "docx" -> a Word document editor card the user edits and downloads.
- generate_file, type "pptx" -> a PowerPoint editor. content = slides separated by a line containing only ---; the first line of each slide is its title.
- run_python -> Python code that runs in the user's browser with Pyodide (Python 3.12 compiled to WebAssembly). The standard library works, and numpy, pandas, scipy, sympy and matplotlib load automatically when imported. Show results with print(). There is no input(), no real file system and no network access from Python. Use single quotes inside the code so the JSON stays valid.

HOW TO THINK
Before you answer, think inside <think> ... </think>. Think freely and for as long as you need. Work out what the user really wants, which of the places above the result is going to, what a finished version must contain, and check your plan. Then close the tag and write only the final output. Never put your thinking inside the email, document or code.

HOW TO USE A TOOL
Reply with ONE JSON object and nothing else after the thinking. Put "tool" first. Formats:

To send an email, mail, Gmail message, message through email, compose an email, write and send an email, reply to an email, forward an email, or send a message to someone's email address, you must always use this:
{"tool":"send_email","to":"a@b.com","subject":"...","body":"..."}
To extract a pdf, perform this:
{
    name: "extract_pdf",
    description: "Extract text from a PDF file",
    input: {
        file: "File"
    },
    execute: async ({ file }) => {
        // Calls your existing PDF extraction logic
    }
}
To create, generate, make, build, write, export, or produce a file, document, Word document, DOCX, report, or downloadable document, you must always use this:
{"tool":"generate_file","type":"docx","filename":"Name.docx","content":"..."}


To run, execute, test, or write Python code, perform a calculation using Python, process data, or automate a task using Python, you must always use this:
{"tool":"run_python","code":"..."}


To create, add, schedule, book, arrange, or set up a calendar event, meeting, appointment, reminder, or scheduled activity, you must always use this:
{"tool":"create_calendar","title":"...","date":"YYYY-MM-DD","time":"HH:MM","duration":"1 hour"}


To create, generate, make, prepare, or issue an invoice, bill, payment request, or client invoice, you must always use this:
{"tool":"create_invoice","client":"..."}


To create, generate, make, or produce a QR code, scan code alternative, or scannable code containing a link, text, or other information, you must always use this:
{"tool":"generate_qr","text":"..."}


