        if (!m) return null;
        let i = m.index + m[0].length, s = "";
        while (i < src.length) {
            const ch = src[i];
            if (ch === "\\") {
                const n = src[i + 1]; if (n === undefined) break;
                if (n === "n") s += "\n"; else if (n === "t") s += "\t";
