RULES
Write complete, full-length content: there is no length limit, so never shorten, summarise or leave a document unfinished. Never use placeholders like [Name] or [Date]; invent real, specific values. Be direct and exact, with no filler.${hint ? "\n\n" + hint : ""}`;
    }

    async function chat(text, targetChat) {
        const sys = buildSys(text);

        let msgs = [{ role: "system", content: sys }, ...targetChat.msgs.slice(-4).filter(m => m.c !== "s").map(m => ({ role: m.c === "u" ? "user" : "assistant", content: m.t }))];
        let toolData = null, attempts = 0, totalOut = "", isDone = false, stopped = false;

        currentGenInterrupt = () => { stopped = true; };
        const claudeBlock = createClaudeBlock(targetChat);
        let kind = null, card = null, live = null, liveBody = null, thinkLine = "";
        const LABELS = { send_email: "Drafting email", generate_file: "Writing document", create_calendar: "Creating event", create_invoice: "Building invoice", generate_qr: "Making QR code", add_task: "Adding task", save_contact: "Saving contact", convert_currency: "Converting currency", weather: "Checking weather", run_python: "Running Python", web_search: "Searching the web", scrape_url: "Reading page" };
        let truncated = true;

        // Called while tokens stream in: routes them straight into their final home (no second pass).
        const tick = (all) => {
            const think = all.match(/<think>([\s\S]*?)(<\/think>|$)/);
            if (think) { const ln = think[1].trim().split("\n").filter(Boolean).pop(); if (ln) thinkLine = ln; }
            const vis = all.replace(/<think>[\s\S]*?(<\/think>|$)/g, "").trimStart();
            if (!kind) {
                const m = vis.match(/"tool"\s*:\s*"(\w+)"/);
                if (m) {
                    kind = m[1];
                    if (kind === "send_email") card = renderInlineEmail({}, targetChat);
                    else if (kind === "generate_file") card = renderInlineDoc("Document.docx", "", targetChat);
                    else if (kind === "run_python") card = renderInlinePython("", targetChat);
                } else if (vis && !/^(```|\{)/.test(vis)) {
                    kind = "text";
                    live = bub("", "a", true, targetChat);
                    if (live) { liveBody = document.createElement("span"); live.prepend(liveBody); }
                }
            }
            if (kind === "text") { setStatus(claudeBlock, thinkLine ? "Thinking: " + thinkLine : "Writing…"); if (liveBody) { liveBody.innerHTML = md(vis); autoscroll(); } }
            else if (kind) {
                setStatus(claudeBlock, (LABELS[kind] || "Running " + kind) + "…");
                if (card && card.fill) {
                    const d = {};
                    for (const k of ["to", "subject", "body", "filename", "content", "code"]) { const v = partialField(vis, k); if (v !== null) d[k] = v; }
                    card.fill(d);
                }
            } else setStatus(claudeBlock, thinkLine ? "Thinking: " + thinkLine : "Thinking…");
        };

        while (truncated && attempts < 3 && !stopped) {
            attempts++; truncated = false;
            let out = "";
            const uiInterval = setInterval(() => tick(totalOut + out), 60);
            try {
                const st = await engine.chat.completions.create({
                    stream: true, temperature: 0.6, max_tokens: 99999, messages: msgs
                });
                for await (const chunk of st) {
                    if (stopped) break;
                    out += chunk.choices[0]?.delta?.content || "";
                    if (chunk.choices[0]?.finish_reason === "length") truncated = true;
                }
            } catch (e) { break; } finally {
                clearInterval(uiInterval);
                tick(totalOut + out);
            }
            if (stopped) break;
            totalOut += out;
            // Only ask the model to continue if it really hit the token limit (not on every parse hiccup).
            if (truncated && attempts < 3) {
                msgs.push({ role: "assistant", content: out });
                msgs.push({ role: "user", content: "Continue EXACTLY from where you left off." });
            }
        }

        const clean = totalOut.replace(/<think>[\s\S]*?(<\/think>|$)/g, "").trim();
        if (stopped) { setStatus(claudeBlock, "Stopped", true); bub("🛑 Generation stopped by user.", "s", false, targetChat); return; }

        try {
            let jsonStr = "";
            const mdMatch = clean.match(/```(?:json)?\n([\s\S]*?)\n```/);
            if (mdMatch) jsonStr = mdMatch[1];
            else { const bm = clean.match(/\{[\s\S]*"tool"[\s\S]*\}/); if (bm) jsonStr = bm[0]; }
            if (jsonStr) {
                const safeJson = jsonStr.replace(/("(?:[^"\\]|\\.)*")/g, m => m.replace(/\n/g, '\\n').replace(/\r/g, ''));
                toolData = JSON.parse(safeJson);
            }
        } catch (e) { toolData = null; }

        if (!toolData || !toolData.tool) {
            // Plain answer: it is already in the bubble while streaming. Just save it.
            if (live) { liveBody.innerHTML = md(clean); targetChat.msgs.push({ t: clean, c: "a" }); }
            else if (clean) bub(clean, "a", false, targetChat);
            if (card && card.remove) card.remove();
            if (claudeBlock) claudeBlock.remove();
            save(); if (S.cur.id === targetChat.id) autoscroll();
            return;
        }

        {
            const t = toolData;
            let successMsg = "";
            setStatus(claudeBlock, (LABELS[t.tool] || t.tool) + "…");
            try {
                if (t.tool === "web_search" && t.query && t.query.startsWith("http")) { t.tool = "scrape_url"; t.url = t.query; }

                if (t.tool === "send_email") {
                    if (card && card.fill) card.fill({ to: t.to, subject: t.subject, body: t.body });
                    else renderInlineEmail({ to: t.to, subject: t.subject, body: t.body }, targetChat);
                } else if (t.tool === "generate_file") {
                    const ftype = (t.type || "docx").toLowerCase();
                    if (ftype === "pptx") { if (card) card.remove(); renderInlinePpt(t.filename || "Presentation.pptx", t.content, targetChat); }
                    else if (card && card.fill) card.fill({ filename: t.filename, content: t.content });
                    else renderInlineDoc(t.filename || "Document.docx", t.content, targetChat);
                } else if (t.tool === "run_python") {
                    if (card && card.fill) card.fill({ code: t.code });
                    else card = renderInlinePython(t.code, targetChat);
